#pragma once
#include <list>
#include <memory>
#include <optional>
#include <string>
#include "../lexer.hpp"
#include "../types.hpp"

// BlitzBasic Built-Ins
// - Include: Followed by a String, which is the file to include at this location.
// - Const: Defines one or more constants, which can not be modified.
// - Local: Defines one or more local variables, which can be modified.
// - Global: Defines one or more global variables, which can be modified from anywhere.
// - Dim: Defines a dynamically resizable array, globally accessible and modifyable.
// - If, Then, ElseIf, EndIf: Your classic If.
// - Select, Case, Default, End Select: Your classic Select.
// - For, To, Step, Next: Your classic For loop.
// - While, Wend: Your classic While loop.
// - Repeat, Until, Forever: Similar to While/Wend, but the condition is at the end and will only loop if the condition is false.
// - Exit: Exit from any currently active loops. I guess this allows leaving Repeat/Forever combinations.
// - True, False: True and False. What, did you expect something else?
// - Stop: Pause the program for the debugger, if there happens to be one.
// - End: Terminate the program.
// - Goto: Jump to a specific label, without setting the return address.
// - Gosub, Return: Jump to a specific label (subroutine), setting the return address appropriately, and Return from it eventually.
// - Function, Return, End Function: Defines a function, and allows returning values. Yes, I know, End itself terminates the program, this is a special case. Thanks younger Sibly.
// - And, Or, Not: Logical operator, self-explanatory really.

#undef NULL

namespace blitz {
	namespace ast {
		struct node {
			std::vector<blitz::token> tokens;

			virtual ~node() = default;
		};

		/* Variable Parsing
		 *
		 * Declaration:
		 * - 8bit Signed Integer Variable
		 *     Variable.Byte
		 *     Variable.Int8
		 * - 8bit Unsigned Integer Variable
		 *     Variable.UByte
		 *     Variable.UInt8
		 * - 16bit Signed Integer Variable
		 *     Variable.Short
		 *     Variable.Int16
		 * - 16bit Unsigned Integer Variable
		 *     Variable.UShort
		 *     Variable.UInt16
		 * - 32bit Signed Integer Variable
		 *     Variable
		 *     Variable%
		 *     Variable.Int
		 *     Variable.Int32
		 * - 32bit Unsigned Integer Variable
		 *     Variable.UInt
		 *     Variable.UInt32
		 * - 64bit Signed Integer Variable
		 *     Variable%%
		 *     Variable.Long
		 *     Variable.Int64
		 * - 64bit Unsigned Integer Variable
		 *     Variable.ULong
		 *     Variable.UInt64
		 * - 32bit Real Variable
		 *     Variable#
		 *     Variable.Float
		 *     Variable.Float32
		 *     Variable.Real
		 *     Variable.Real32
		 * - 64bit Real Variable
		 *     Variable##
		 *     Variable.Double
		 *     Variable.Float64
		 *     Variable.Real64
		 * - UTF-8 String Variable
		 *     Variable$
		 *     Variable.String
		 * - Struct Variable
		 *     Variable.StructName
		 *
		 * Access:
		 * - Struct Access:
		 *     Variable\Key
		 * - Array Access:
		 *     Variable[IntegerIndex]
		 * - Dynamic Array Access:
		 *     Variable(IntegerIndex)
		 * - Direct Access:
		 *     Variable
		 */
		struct variable : public node {
			std::string        name;
			blitz::types::type type;
			std::string        struct_name;

			virtual ~variable();

			static bool                              can_parse(std::shared_ptr<blitz::lexer> lexer);
			static std::shared_ptr<blitz::ast::node> try_parse(std::shared_ptr<blitz::lexer> lexer);
		};
		
		/** Value Parsing
		 *
		 * Handles parsing of:
		 * - True
		 * - False
		 * - Null
		 * - Any Integer Values including 0x, 0b and 0 notation with or without u suffix for unsigned.
		 * - Any Real Values
		 * - Any String Values
		 */
		struct value : public node {
			enum class variant {
				UNKNOWN,
				NULL,
				BOOL,
				INTEGER,
				UNSIGNED_INTEGER,
				REAL,
				STRING,
			} type;
			union {
				bool      b;
				intmax_t  i;
				uintmax_t ui;
				double    f;
			} number;
			std::string text;

			virtual ~value();

			static bool                              can_parse(std::shared_ptr<blitz::lexer> lexer);
			static std::shared_ptr<blitz::ast::node> try_parse(std::shared_ptr<blitz::lexer> lexer);
		};

		/* Variable Declaration
		 *
		 * Examples:
		 * - Local myVar1, myVar2%, myVar3 = "Help", myVar4$ = "Me"
		 * - Global myVar2g# = 3.147
		 * - Dim myDynamicArray[128]
		 *
		 *
		 *
		 */
		struct declare : public node {
			// Local, Global
			bool                                         global;
			std::list<std::shared_ptr<blitz::ast::node>> nodes;

			virtual ~declare();

			static bool                              can_parse(std::shared_ptr<blitz::lexer> lexer);
			static std::shared_ptr<blitz::ast::node> try_parse(std::shared_ptr<blitz::lexer> lexer);
		};

		struct expression : public node {};
	} // namespace ast
} // namespace blitz
